/**
 * Ícono de Simple Icons de una empresa, o `null` si no está mapeada.
 *
 * Comparación case-insensitive y tolerante a espacios extra, igual que `companyColor` en
 * `ui/theme/StateColors.kt`.
 */
fun companySimpleIcon(company: String): CompanyIcon? =
    CompanySimpleIcons[company.trim().lowercase()]
